import React, { useState } from 'react';
import chatBgImg from '../assets/nen_ten_web.jpg'; // Dùng ảnh tòa nhà làm nền chat cho xịn

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('all');

    return (
        <div style={{
            flex: 1, 
            borderRadius: '30px', 
            display: 'flex', 
            flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, 
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            overflow: 'hidden'
        }} className="glass-card fade-in">

            <div style={styles.headerTabs}>
                <button 
                    onClick={() => setTabActive('all')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.6)', color: tabActive === 'all' ? '#fff' : '#333'}}
                >
                    Mọi người
                </button>
                <button 
                    onClick={() => setTabActive('private')}
                    style={{...styles.tabBtn, backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.6)', color: tabActive === 'private' ? '#fff' : '#333'}}
                >
                    Gửi riêng
                </button>
            </div>

            <div style={styles.contentBody}>
                {tabActive === 'all' ? (
                    <div style={styles.chatArea}>
                        <div style={styles.messages}>
                            <div style={styles.msgLeft}>
                                <div style={styles.avatar}>105</div>
                                <div style={styles.bubble}>Chào cả nhà, chúc mọi người ngày mới tốt lành!</div>
                            </div>
                        </div>
                        <div style={styles.inputBox}>
                            <input style={styles.input} placeholder="Gửi tin nhắn đến mọi người..." />
                            <button style={styles.btn}>Gửi</button>
                        </div>
                    </div>
                ) : (
                    <div style={styles.privateView}>
                        <div style={styles.roomList}>
                            {[101, 102, 103, 104, 201, 202, 203, 204].map(room => (
                                <div key={room} className="room-item">{room}</div>
                            ))}
                        </div>
                        <div style={styles.privateChat}>
                            <p style={{color: '#fff', textShadow: '1px 1px 5px #000'}}>Chọn phòng để bắt đầu chat riêng</p>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    headerTabs: { padding: '20px', display: 'flex', gap: '15px' },
    tabBtn: { padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s' },
    contentBody: { flex: 1, padding: '0 20px 20px 20px', display: 'flex', overflow: 'hidden' },
    chatArea: { flex: 1, display: 'flex', flexDirection: 'column' },
    messages: { flex: 1, padding: '10px' },
    msgLeft: { display: 'flex', gap: '10px', alignItems: 'center' },
    avatar: { width: '35px', height: '35px', borderRadius: '50%', backgroundColor: '#333', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' },
    bubble: { backgroundColor: 'rgba(255,255,255,0.9)', padding: '12px 18px', borderRadius: '18px 18px 18px 0', fontSize: '13px' },
    inputBox: { display: 'flex', gap: '10px' },
    input: { flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' },
    btn: { padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold' },
    privateView: { flex: 1, display: 'flex', gap: '20px' },
    roomList: { width: '150px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', alignContent: 'flex-start' },
    privateChat: { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center' }
};

export default QuanLyThongBao;
